import com.google.gson.*;
import dev.hua.ptcglive.engine.*;
import dev.hua.ptcglive.engine.effect.*;
import dev.hua.ptcglive.engine.field.*;
import dev.hua.ptcglive.rules.*;
import java.util.*;

/** Two owners decide in printed order without handing the attack or private cards to the other player. */
public final class OpponentEnergyAttachmentTest {
    static final UUID A=GeneratedRuleBatch8Test.A,B=GeneratedRuleBatch8Test.B,WATCH=new UUID(0,8100);
    static final String OWN="{\"type\":\"attach_energy\",\"target\":\"SELECT_OWN_POKEMON\",\"source\":\"HAND\",\"amount\":3,\"minimum\":0,\"basic_energy_only\":true,\"target_scope\":\"OWN_FIELD\",\"distribution\":\"ANY\"}";
    static final String OTHER=OWN.replace("SELECT_OWN_POKEMON","SELECT_OPPONENT_POKEMON").replace("OWN_FIELD","OPPONENT_FIELD").replace("\"distribution\":\"ANY\"","\"distribution\":\"ANY\",\"source_owner\":\"OPPONENT\",\"chooser\":\"OPPONENT\"");
    static void check(boolean b,String s){GeneratedRuleBatch8Test.check(b,s);}
    static void reject(Runnable r){GeneratedRuleBatch8Test.reject(r);}
    static UUID active(ServerMatch m,UUID p){return m.activePokemonView(p).pokemonId();}
    static AttackDefinition attack(){return DamageTriggeredAbilityTest.attack(0,SourceEnergyCounterTest.after(OTHER+","+OWN));}
    static ServerMatch game(){return GeneratedRuleBatch46Test.baseFixture(attack(),0,EnergyType.WATER);}
    static List<CardInstance> choose(ServerMatch m,UUID p,int count){var c=m.effectCardPrompt(p);var cards=c.candidates().stream().limit(count).toList();check(cards.size()==count,"Fixture lacks energies");m.submitEffectCards(p,c.resolutionId(),c.step(),cards.stream().map(CardInstance::instanceId).toList());return cards;}
    static void distribute(ServerMatch m,UUID p,List<CardInstance> cards){var a=m.effectAttachmentPrompt(p);int i=0;for(var c:cards)m.assignEffectEnergyDistribution(p,a.resolutionId(),a.step(),c.instanceId(),i++%2==0?active(m,p):m.benchPokemonView(p).getFirst().pokemonId());m.confirmEffectEnergyDistribution(p,a.resolutionId(),a.step());}
    public static void main(String[] args){orderPrivacyAndAuthority();independentDeclines();emptyOpponent();immunityOrigin();staleCards();copied();energyEvents();schema();System.out.println("OpponentEnergyAttachmentTest passed: opponent-first private hand and public assignments, independent decline and empty sources, original effect origin/protection, session visibility/authority, strict Basic selection/max3/own hosts, stale/replayed requests, actual copy controller, deferred own-hand attachment events and schema/phase rejection");}
    static void orderPrivacyAndAuthority(){var m=game();var session=MatchSession.multiplayer(m,A,B);session.addSpectator(WATCH);int rng=m.randomTranscript().size();m.attack(A,attack().id());check(m.pendingChoicePlayer().equals(B)&&m.currentPlayer().equals(A),"Attack ownership changed or owner went first");var select=m.effectCardPrompt(B);check(select.minimum()==0&&select.maximum()==3&&select.candidates().stream().allMatch(c->c.ownerId().equals(B)&&m.cardDefinition(c.definitionId()).basicEnergy()),"Private candidates contain wrong owner/nonbasic");
        for(UUID p:List.of(A,WATCH)){reject(()->m.effectCardPrompt(p));var view=session.view(p,p.equals(A)?A:null);check(view.game().effectSelection()==null&&view.options().stream().noneMatch(o->o.labelZh().startsWith("选择卡牌")),"Wrong seat sees/selects hand");}
        reject(()->m.submitEffectCards(A,select.resolutionId(),select.step(),List.of()));reject(()->m.submitEffectCards(B,select.resolutionId(),select.step(),List.of(m.privateView(B).hand().stream().filter(c->c.definitionId().equals("special")).findFirst().orElseThrow().instanceId())));
        var before=m.clientView(B);reject(()->m.submitEffectCards(B,select.resolutionId(),select.step(),select.candidates().stream().limit(4).map(CardInstance::instanceId).toList()));reject(()->m.submitEffectCards(B,select.resolutionId(),select.step(),List.of(select.candidates().getFirst().instanceId(),select.candidates().getFirst().instanceId())));reject(()->m.submitEffectCards(B,select.resolutionId(),select.step()+1,List.of()));reject(()->m.submitEffectCards(B,select.resolutionId(),select.step(),List.of(m.privateView(A).hand().getFirst().instanceId())));reject(()->m.endTurn(B));check(before.equals(m.clientView(B)),"Rejected choice changed state");
        var chosen=choose(m,B,3);var prompt=m.effectAttachmentPrompt(B);check(m.pendingChoicePlayer().equals(B),"Distribution gave attacker control");for(UUID p:List.of(A,WATCH)){reject(()->m.effectAttachmentPrompt(p));String view=new Gson().toJson(session.view(p,p.equals(A)?A:null));for(var c:chosen)check(!view.contains(c.instanceId().toString()),"Opponent selected hidden Energy leaked");}
        reject(()->m.assignEffectEnergyDistribution(A,prompt.resolutionId(),prompt.step(),chosen.getFirst().instanceId(),active(m,B)));reject(()->m.assignEffectEnergyDistribution(B,prompt.resolutionId(),prompt.step(),chosen.getFirst().instanceId(),active(m,A)));reject(()->m.confirmEffectEnergyDistribution(B,prompt.resolutionId(),prompt.step()));
        for(int i=0;i<chosen.size();i++){var view=session.view(B,B);UUID target=i%2==0?active(m,B):m.benchPokemonView(B).getFirst().pokemonId();String key="effect-source:"+chosen.get(i).instanceId();var option=view.options().stream().filter(o->o.cardKeys().contains(key)&&o.cardKeys().contains("field:"+target)).findFirst().orElseThrow();session.submit(B,B,view.revision(),option.index());}
        var view=session.view(B,B);var confirm=view.options().stream().filter(o->o.labelZh().startsWith("确认能量分配")).findFirst().orElseThrow();session.submit(B,B,view.revision(),confirm.index());
        check(m.activePokemonView(B).attachedEnergyIds().size()==2&&m.benchPokemonView(B).getFirst().attachedEnergyIds().size()==1&&m.pendingChoicePlayer().equals(A),"Opponent did not finish attachments before owner decision");reject(()->m.submitEffectCards(B,select.resolutionId(),select.step(),List.of()));reject(()->m.confirmEffectEnergyDistribution(B,prompt.resolutionId(),prompt.step()));
        var own=choose(m,A,2);distribute(m,A,own);check(m.currentPlayer().equals(B)&&!m.hasPendingEffectChoice()&&m.activePokemonView(A).attachedEnergyIds().size()==1&&m.benchPokemonView(A).getFirst().attachedEnergyIds().size()==1&&m.randomTranscript().size()==rng,"Both-player completion/turn/RNG");
    }
    static void independentDeclines(){for(int other:List.of(0,1))for(int own:List.of(0,1)){var m=game();m.attack(A,attack().id());var cs=choose(m,B,other);if(other>0)distribute(m,B,cs);check(m.pendingChoicePlayer().equals(A),"Opponent decline skipped owner's choice");cs=choose(m,A,own);if(own>0)distribute(m,A,cs);check(m.activePokemonView(B).attachedEnergyIds().size()==other&&m.activePokemonView(A).attachedEnergyIds().size()==own&&!m.hasPendingEffectChoice(),"Independent optional choices coupled");}}
    static void emptyOpponent(){var m=game();m.discardHandCardsByEffect(A,B,m.privateView(B).hand().stream().filter(c->m.cardDefinition(c.definitionId()).basicEnergy()).map(CardInstance::instanceId).toList());m.attack(A,attack().id());check(m.pendingChoicePlayer().equals(A),"No eligible opponent Energy stranded");distribute(m,A,choose(m,A,1));check(m.currentPlayer().equals(B),"Empty opponent interrupted own attachment");}
    static void immunityOrigin(){var m=game();m.endTurn(A);var shield=EffectRegistry.standard().parse(JsonParser.parseString(EffectOriginProtectionTest.shield("ATTACK","EFFECTS_ONLY","SELF","LEAVES_PLAY")).getAsJsonObject());m.executeEffectProgramByRule(B,active(m,B),new EffectProgram(List.of(new TriggeredEffects(EffectTrigger.ON_CARD_PLAYED,List.of(),List.of(shield)))),EffectTrigger.ON_CARD_PLAYED);m.endTurn(B);m.attack(A,attack().id());var cs=choose(m,B,2);distribute(m,B,cs);check(m.activePokemonView(B).attachedEnergyIds().isEmpty()&&m.privateView(B).hand().contains(cs.getFirst())&&m.benchPokemonView(B).getFirst().attachedEnergyIds().contains(cs.getLast().instanceId()),"Chooser replaced original opposing attack origin");choose(m,A,0);}
    static void staleCards(){var m=game();m.attack(A,attack().id());var cs=choose(m,B,1);var prompt=m.effectAttachmentPrompt(B);m.assignEffectEnergyDistribution(B,prompt.resolutionId(),prompt.step(),cs.getFirst().instanceId(),active(m,B));GeneratedRuleBatch46Test.zone(m,"hand").remove(cs.getFirst());GeneratedRuleBatch46Test.zone(m,"discard").add(cs.getFirst());var before=m.clientView(B);reject(()->m.confirmEffectEnergyDistribution(B,prompt.resolutionId(),prompt.step()));check(before.equals(m.clientView(B)),"Stale selected card changed state");}
    static void copied(){var m=CopyAttackTest.fixture(attack());CopyAttackTest.pay(m);CopyAttackTest.copy(m,CopyAttackTest.choice(m),List.of(),List.of());check(m.pendingChoicePlayer().equals(CopyAttackTest.B),"Copied attack chose the text owner's opponent");choose(m,CopyAttackTest.B,0);check(m.pendingChoicePlayer().equals(CopyAttackTest.A),"Copied attack lost actual controller");choose(m,CopyAttackTest.A,0);check(m.currentPlayer().equals(CopyAttackTest.B)&&!m.hasPendingEffectChoice(),"Copied attack did not end actual actor turn");}
    static ServerMatch eventGame(){
        var ability=BundledCombatData.ability(JsonParser.parseString("{\"id\":\"own-hand\",\"nameZh\":\"Own hand event fixture\",\"kind\":\"TRIGGERED\",\"effectSupport\":\"SUPPORTED\",\"eventPolicy\":{\"target\":\"SELF\",\"source\":\"HAND\",\"cause\":\"EFFECT\",\"optional\":false,\"usage\":\"NONE\",\"ownHandOnly\":true},\"triggers\":[{\"trigger\":\"ON_ENERGY_ATTACHED\",\"effects\":[{\"type\":\"draw\",\"amount\":1}]}]}").getAsJsonObject(),EffectRegistry.standard());
        var defs=new ArrayList<CardDefinition>();for(String id:List.of("base","energy"))defs.add(new CardDefinition(id,id,id.equals("base")?CardCategory.POKEMON:CardCategory.ENERGY,TrainerCategory.NONE,"J",Set.of("international"),id.equals("base"),id.equals("energy"),60,Map.of(),EffectSupport.SUPPORTED,null));
        var catalog=new CombatCatalog(Map.of("base",new PokemonProfile(500,1,null,null,0,null,0,1,List.of(attack()),List.of(ability),EnergyType.COLORLESS)),Map.of("energy",EnergyType.GRASS));
        for(int seed=0;seed<500;seed++){var decks=new ArrayList<List<CardInstance>>();for(UUID owner:List.of(A,B)){var cs=new ArrayList<CardInstance>();for(int i=0;i<60;i++)cs.add(new CardInstance(new UUID(owner.getLeastSignificantBits(),i+1),owner,i<24?"base":"energy"));decks.add(cs);}var m=new ServerMatch(A,B,decks.getFirst(),decks.getLast(),GeneratedRuleBatch8Test.RULES,new CardDatabase(defs),catalog,new ServerRandom(seed));OpeningTestSupport.decideOrder(m,A,B);if(List.of(A,B).stream().anyMatch(p->m.privateView(p).hand().stream().filter(c->c.definitionId().equals("base")).count()<2))continue;OpeningTestSupport.complete(m,A,B,1);m.drawCardsByEffect(A,A,10);m.drawCardsByEffect(A,B,10);m.endTurn(A);m.endTurn(B);return m;}throw new AssertionError("No attachment-event fixture");
    }
    static void energyEvents(){var m=eventGame();int a=m.privateView(A).deck().size(),b=m.privateView(B).deck().size();m.attack(A,attack().id());distribute(m,B,choose(m,B,1));check(m.privateView(A).deck().size()==a&&m.privateView(B).deck().size()==b&&m.triggerOrderPrompt()==null&&m.pendingChoicePlayer().equals(A),"Attachment trigger ran between the two decisions");distribute(m,A,choose(m,A,1));check(m.privateView(A).deck().size()==a-1&&m.privateView(B).deck().size()==b-2&&m.currentPlayer().equals(B)&&!m.hasPendingEffectChoice(),"Own-hand trigger lost source owner or automatic opponent controller");}
    static void schema(){for(String bad:List.of(OTHER.replace("\"source_owner\":\"OPPONENT\",",""),OTHER.replace("\"chooser\":\"OPPONENT\"","\"chooser\":\"SELF\""),OTHER.replace("\"HAND\"","\"DECK\""),OTHER.replace("\"minimum\":0","\"minimum\":1"),OTHER.replace("\"basic_energy_only\":true","\"basic_energy_only\":false"),OTHER.replace("OPPONENT_FIELD","OWN_FIELD"),OTHER.replace("\"ANY\"","\"SAME_TARGET\"")))reject(()->AttackProgramRules.validate(DamageTriggeredAbilityTest.attack(0,SourceEnergyCounterTest.after(bad))));
        var e=EffectRegistry.standard().parse(JsonParser.parseString(OTHER).getAsJsonObject());for(var t:List.of(EffectTrigger.BEFORE_ATTACK,EffectTrigger.ONCE_PER_TURN,EffectTrigger.ON_CARD_PLAYED)){var p=new EffectProgram(List.of(new TriggeredEffects(t,List.of(),List.of(e))));reject(()->ResumableProgramRules.validate(p,t!=EffectTrigger.ON_CARD_PLAYED,t));}
    }
}
